return ['domain'=>'sofreh-phone-accounts','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fa_IR','project-id-version'=>'Sofreh Phone Accounts 1.1.0','pot-creation-date'=>'2026-10-12T17:30:23+00:00','po-revision-date'=>'2026-10-12 12:00+0330','x-generator'=>'WP-CLI 2.12.0','messages'=>['Sofreh Phone Accounts'=>'حساب کاربری با شماره موبایل (سفره)','https://github.com/yns-nur/nur/tree/main/wp-theme/sofreh-phone-accounts'=>'https://github.com/yns-nur/nur/tree/main/wp-theme/sofreh-phone-accounts','Customers buy with just their mobile number. A customer account is created automatically when the order is placed, and the order confirmation page shows the order tracking code together with the login details (mobile number as username, plus a generated password). Adds an order-tracking form that works with order number and mobile number. Companion to the Sofreh theme, but works with any theme.'=>'مشتری فقط با شماره موبایل خرید می‌کند. هنگام ثبت سفارش حساب کاربری به‌صورت خودکار ساخته می‌شود و صفحهٔ تأیید سفارش، کد پیگیری را همراه با اطلاعات ورود (شماره موبایل به‌عنوان نام کاربری و یک رمز عبور ساخته‌شده) نشان می‌دهد. فرم پیگیری سفارش با کد پیگیری و شماره موبایل نیز اضافه می‌شود. همراه پوستهٔ سفره، اما با هر پوسته‌ای کار می‌کند.','Younes Nur'=>'یونس نور','Track your order'=>'پیگیری سفارش','Please enter a valid mobile number, for example 09121234567. It becomes your username for signing in.'=>'لطفاً شماره موبایل معتبر وارد کنید، مثلاً 09121234567. این شماره نام کاربری شما برای ورود خواهد بود.','Mobile number'=>'شماره موبایل','Your account is created with this number; you will see your password after placing the order.'=>'حساب کاربری شما با همین شماره ساخته می‌شود؛ رمز عبور را پس از ثبت سفارش می‌بینید.','Customer account created automatically from the mobile number.'=>'حساب کاربری مشتری به‌صورت خودکار با شماره موبایل ساخته شد.','Your order tracking code'=>'کد پیگیری سفارش شما','Use it with your mobile number on the <a href="%s">order tracking page</a>.'=>'با این کد و شماره موبایلتان در <a href="%s">صفحهٔ پیگیری سفارش</a> وضعیت سفارش را ببینید.','Keep it to follow up on your order.'=>'این کد را برای پیگیری سفارش نگه دارید.','Copy tracking code'=>'کپی کد پیگیری','Your account has been created'=>'حساب کاربری شما ساخته شد','You are signed in. Use these details to sign in next time, then complete your account information whenever you like.'=>'اکنون وارد حساب خود شده‌اید. دفعهٔ بعد با این اطلاعات وارد شوید و هر زمان خواستید اطلاعات حسابتان را کامل کنید.','Username (your mobile number)'=>'نام کاربری (شماره موبایل شما)','Copy username'=>'کپی نام کاربری','Password'=>'رمز عبور','Copy password'=>'کپی رمز عبور','Write the password down or save it now: for your security it is shown only on this page, for %s minutes, and is never sent by email or text message.'=>'همین حالا رمز عبور را یادداشت یا ذخیره کنید: برای امنیت شما فقط در همین صفحه و تا %s دقیقه نمایش داده می‌شود و هرگز با ایمیل یا پیامک فرستاده نمی‌شود.','Complete your account'=>'تکمیل اطلاعات حساب','Go to my account'=>'رفتن به حساب من','If you already have an account with this mobile number, <a href="%s">sign in</a> to see your orders there.'=>'اگر از قبل با این شماره موبایل حساب کاربری دارید، برای دیدن سفارش‌هایتان <a href="%s">وارد شوید</a>.','Copy'=>'کپی','Copied'=>'کپی شد','Copied to clipboard'=>'در کلیپ‌بورد کپی شد','Mobile number or email'=>'شماره موبایل یا ایمیل','Bought with your mobile number? Sign in with that number and the password shown after your purchase.'=>'با شماره موبایل خرید کرده‌اید؟ با همان شماره و رمز عبوری که پس از خرید نمایش داده شد وارد شوید.','Your account was created with your mobile number. Add your name and email and choose your own password.'=>'حساب شما با شماره موبایلتان ساخته شده است. نام و ایمیل خود را اضافه کنید و رمز عبور دلخواهتان را انتخاب کنید.','Complete account'=>'تکمیل حساب','Required'=>'الزامی','You will sign in with this number.'=>'با همین شماره وارد حساب کاربری می‌شوید.','An account with this mobile number already exists. Please sign in instead.'=>'با این شماره موبایل قبلاً حساب کاربری ساخته شده است. لطفاً وارد شوید.','The form has expired. Please try again.'=>'اعتبار فرم تمام شده است. لطفاً دوباره تلاش کنید.','No order matches this tracking code and mobile number.'=>'سفارشی با این کد پیگیری و شماره موبایل پیدا نشد.','Enter the tracking code shown after your purchase and the mobile number you ordered with.'=>'کد پیگیری‌ای را که پس از خرید دریافت کردید و شماره موبایلی را که با آن سفارش دادید وارد کنید.','Tracking code'=>'کد پیگیری','Track order'=>'پیگیری سفارش','Order %s'=>'سفارش %s','Status'=>'وضعیت','Date'=>'تاریخ','Total'=>'مبلغ کل','View full order'=>'مشاهدهٔ کامل سفارش']];